function check([s], actual, expected) {
  if (typeof actual !== 'string' || actual.length !== expected.length) return false;
  if (actual === '') return true;
  const first = s.indexOf(actual);
  return first !== -1 && s.indexOf(actual, first + 1) !== -1;
}

