function validate([s]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 30000) return 's has 2 to 3 * 10^4 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may only contain lowercase English letters.';
  return null;
}

