function longestDupSubstring(s) {
  const MOD = 1000000007;
  const BASE = 31;
  const n = s.length;
  const codes = Array.from(s, ch => ch.charCodeAt(0) - 96);

  const findRepeat = length => {
    let power = 1;
    for (let i = 0; i < length; i++) {
      power = (power * BASE) % MOD;
    }
    const seen = new Map();
    let hash = 0;
    for (let i = 0; i < n; i++) {
      hash = (hash * BASE + codes[i]) % MOD;
      if (i >= length) {
        hash = (hash - (codes[i - length] * power) % MOD + MOD) % MOD;
      }
      if (i < length - 1) {
        continue;
      }
      const start = i - length + 1;
      const window = s.slice(start, i + 1);
      const starts = seen.get(hash) ?? [];
      for (const other of starts) {
        if (s.slice(other, other + length) === window) {
          return start;
        }
      }
      starts.push(start);
      seen.set(hash, starts);
    }
    return -1;
  };

  let answer = '';
  let low = 1;
  let high = n - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const start = findRepeat(mid);
    if (start !== -1) {
      answer = s.slice(start, start + mid);
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return answer;
}

