function longestDupSubstring(s) {
  // Try every length from longest to shortest and collect that length's substrings in a set.
  for (let length = s.length - 1; length >= 1; length--) {
    const seen = new Set();
    for (let start = 0; start + length <= s.length; start++) {
      const piece = s.substring(start, start + length);
      if (seen.has(piece)) return piece;
      seen.add(piece);
    }
  }
  return '';
}

