function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const randomText = (length, alphabet) => Array.from({ length }, () => letters[int(0, alphabet - 1)]).join('');
  if (size === 'small') {
    const n = int(2, 14);
    const r = rand();
    if (r < 0.1) return [letters.slice(0, Math.min(n, 26))];
    if (r < 0.2) return [letters[int(0, 25)].repeat(n)];
    if (r < 0.35) {
      const unit = randomText(int(1, 4), int(2, 4));
      return [unit.repeat(Math.ceil(n / unit.length)).slice(0, Math.max(2, n))];
    }
    return [randomText(n, int(2, 6))];
  }
  const n = int(8000, 10000);
  const r = rand();
  if (r < 0.15) return ['z'.repeat(n)];
  if (r < 0.3) {
    // A periodic text: the answer is everything but the first period.
    const unit = randomText(int(2, 40), 26);
    return [unit.repeat(Math.ceil(n / unit.length)).slice(0, n)];
  }
  if (r < 0.65) {
    // Random text with one long block copied to a second place.
    const text = randomText(n, int(4, 26)).split('');
    const length = int(50, 3000);
    const from = int(0, n - length), to = int(0, n - length);
    for (let k = 0; k < length; k++) text[to + k] = text[from + k];
    return [text.join('')];
  }
  return [randomText(n, int(2, 26))];
}
